const lock = queen.lock('daily-report', { ttl: '30s' })
if (!(await lock.acquire({ wait: '10s' }))) return   // somebody else holds it
try {
  const res = await queen.transaction()
    .guard(lock)                                    // commits only while the lock is ours
    .queue('reports').push([{ data: report }])
    .commit()
  if (res.success === false) return                 // replaced: nothing was written
} finally {
  await lock.release()
}

