Lock lock = client.lock("daily-report", 30);       // 30 s lifetime
if (!lock.acquire(5000)) return;                    // up to 5 s for our turn
for (const auto& page : pages) {
    if (!lock.keep_alive()) break;                  // lost: stop
    client.transaction()
        .guard(lock)                                // commits only while the lock is ours
        .kv("reports").put(page.id, page.body, KvTtl::seconds(86400))
        .commit();
}
lock.release();
